BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL statement_timeout='20s'; SELECT jsonb_build_object('observedAt',clock_timestamp(),'readOnly',current_setting('transaction_read_only'),'relations',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'columns',(SELECT jsonb_agg(a.attname ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('organizations','organization_members','business_api_keys','api_usage_events','profiles')),'quotaFunctions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'settings',p.proconfig,'securityDefiner',p.prosecdef,'definition',pg_get_functiondef(p.oid),'sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),'anonExecute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticatedExecute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'serviceExecute',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='consume_business_api_quota'),'preparedTransactions',(SELECT count(*) FROM pg_prepared_xacts WHERE database=current_database()),'scopedLocks',(SELECT count(*) FROM pg_locks WHERE relation IN(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('profiles','organizations','organization_members','business_api_keys','api_usage_events','calculation_history','saved_scenarios','calculation_projects','calculator_catalog_admin')) AND pid IS DISTINCT FROM pg_backend_pid())) AS evidence; COMMIT;
